class ULTOSC(API_base):
    """
    Calculates the Ultimate Oscillator (ULTOSC) for a given symbol and interval, providing overbought and oversold signals.
    """
    def __init__(self):
        pass

    def execute(self, **params):
        expected_params = set(["p_symbol", "p_interval", "p_time_period_1", "p_time_period_2", "p_time_period_3", "p_outputsize"])
        unexpected_params = set(params.keys()) - expected_params 
        if unexpected_params:
            return self.handle_error(f"Unexpected parameters: {', '.join(unexpected_params)}", 400)
        p_symbol = params.get('p_symbol', None)
        if p_symbol is None:
            return self.handle_error(f"Required parameter 'p_symbol' is missing", 400)
        is_valid, error = self.validate_type(p_symbol, 'p_symbol', str)
        if not is_valid:
            return error
        
        p_interval = params.get('p_interval', None)
        if p_interval is None:
            return self.handle_error(f"Required parameter 'p_interval' is missing", 400)
        is_valid, error = self.validate_type(p_interval, 'p_interval', str)
        if not is_valid:
            return error
        
        _default_p_time_period_1 = float(7.0) if 7.0 != "" else 0.0
        p_time_period_1 = params.get('p_time_period_1', _default_p_time_period_1)
        if p_time_period_1 is not None:
            is_valid, error = self.validate_type(p_time_period_1, 'p_time_period_1', (float, int))
            if not is_valid:
                return error
        if p_time_period_1 is not None:
            p_time_period_1 = float(p_time_period_1)
        
        _default_p_time_period_2 = float(7.0) if 7.0 != "" else 0.0
        p_time_period_2 = params.get('p_time_period_2', _default_p_time_period_2)
        if p_time_period_2 is not None:
            is_valid, error = self.validate_type(p_time_period_2, 'p_time_period_2', (float, int))
            if not is_valid:
                return error
        if p_time_period_2 is not None:
            p_time_period_2 = float(p_time_period_2)
        
        _default_p_time_period_3 = float(7.0) if 7.0 != "" else 0.0
        p_time_period_3 = params.get('p_time_period_3', _default_p_time_period_3)
        if p_time_period_3 is not None:
            is_valid, error = self.validate_type(p_time_period_3, 'p_time_period_3', (float, int))
            if not is_valid:
                return error
        if p_time_period_3 is not None:
            p_time_period_3 = float(p_time_period_3)
        
        _default_p_outputsize = float(7.0) if 7.0 != "" else 0.0
        p_outputsize = params.get('p_outputsize', _default_p_outputsize)
        if p_outputsize is not None:
            is_valid, error = self.validate_type(p_outputsize, 'p_outputsize', (float, int))
            if not is_valid:
                return error
        if p_outputsize is not None:
            p_outputsize = float(p_outputsize)
        
        return {
            "status_code": 200, 
            "results": {
                "function_name": "ULTOSC",
                "p_symbol": p_symbol,
                "p_interval": p_interval,
                "p_time_period_1": p_time_period_1,
                "p_time_period_2": p_time_period_2,
                "p_time_period_3": p_time_period_3,
                "p_outputsize": p_outputsize
            }
        }

