        is_valid, error = self.validate_type(p_game_id, 'p_game_id', str)
        if not is_valid:
            return error
        
        p_settings = params.get('p_settings', None)
        if p_settings is None:
            return self.handle_error(f"Required parameter 'p_settings' is missing", 400)
        is_valid, error = self.validate_type(p_settings, 'p_settings', dict)
        if not is_valid:
            return error
        

        p_difficulty = p_settings.get('p_difficulty', None)
