        is_valid, error = self.validate_type(p_difficulty, 'p_difficulty', str)
        if not is_valid:
            return error
        
        if p_difficulty is not None and p_difficulty not in ["Easy", "Medium", "Hard", "Expert"]:
            return self.handle_error(f"Parameter 'p_difficulty' not in valid enum", 400)
        
        p_time_of_day = p_settings.get('p_time_of_day', None)
        if p_time_of_day is not None:
            is_valid, error = self.validate_type(p_time_of_day, 'p_time_of_day', str)
